from fastcore.all import *
from fasttransform import Transform
from .dataloader import TensorSpectrum

# %% ../nbs/02_transforms.ipynb #b2d8945f
class BatchSNV(Transform):
    "Center and scale each spectrum by its own mean and standard deviation (SNV)"
    def __init__(self, eps=1e-6): store_attr()
    def encodes(self, x:TensorSpectrum): return (x - x.mean(-1, keepdim=True)) / (x.std(-1, unbiased=False, keepdim=True) + self.eps)

